datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id              Int      @id @default(autoincrement())
  username        String   @unique
  password        String
  role            String   // "CUSTOMER", "AGENT", "MANAGER"
  assignedTickets Ticket[] @relation("AssigneeRelation")
  createdTickets  Ticket[] @relation("CreatorRelation")
}

model Ticket {
  id           Int      @id @default(autoincrement())
  title        String
  description  String
  priority     String   // "HIGH", "MEDIUM", "LOW"
  status       String   @default("OPEN") // "OPEN", "RESOLVED"
  createdAt    DateTime @default(now())
  slaDeadline  DateTime
  isEscalated  Boolean  @default(false)

  assignee     User?    @relation("AssigneeRelation", fields: [assigneeId], references: [id])
  assigneeId   Int?

  creator      User     @relation("CreatorRelation", fields: [creatorId], references: [id])
  creatorId    Int
}

import { defineUserSignupFields } from 'wasp/server/auth'

export const userSignupFields = defineUserSignupFields({
  username: (data) => {
    if (!data.username) {
      throw new Error('Username is required')
    }
    return data.username
  },
  password: (data) => {
    // Wasp stores the hashed password in AuthIdentity, but we also save the password (or hashed/plain text)
    // on the User model as requested by the requirements.
    return data.password || 'password123'
  },
  role: (data) => {
    return data.role || 'CUSTOMER'
  }
})

import { HttpError } from 'wasp/server'

export const getTickets = async (_args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }
  return context.entities.Ticket.findMany({
    include: {
      assignee: true,
      creator: true
    },
    orderBy: {
      createdAt: 'desc'
    }
  })
}

export const getAgents = async (_args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const agents = await context.entities.User.findMany({
    where: {
      role: 'AGENT'
    },
    include: {
      assignedTickets: {
        where: {
          status: {
            not: 'RESOLVED'
          }
        }
      }
    },
    orderBy: {
      id: 'asc'
    }
  })

  return agents.map((agent: any) => ({
    id: agent.id,
    username: agent.username,
    role: agent.role,
    workload: agent.assignedTickets.length
  }))
}

export const createTicket = async (args: { title: string; description: string; priority: 'HIGH' | 'MEDIUM' | 'LOW' }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const { title, description, priority } = args
  if (!title || !description || !priority) {
    throw new HttpError(400, 'Title, description and priority are required')
  }

  // 1. Calculate SLA deadline
  const now = new Date()
  let seconds = 86400 // LOW: 24 hours
  if (priority === 'HIGH') {
    seconds = 3600 // HIGH: 1 hour
  } else if (priority === 'MEDIUM') {
    seconds = 14400 // MEDIUM: 4 hours
  }
  const slaDeadline = new Date(now.getTime() + seconds * 1000)

  // 2. Find agent with lowest workload
  const agents = await context.entities.User.findMany({
    where: {
      role: 'AGENT'
    },
    include: {
      assignedTickets: {
        where: {
          status: {
            not: 'RESOLVED'
          }
        }
      }
    }
  })

  let assigneeId: number | null = null
  if (agents.length > 0) {
    // Sort agents by active ticket count, then by ID
    agents.sort((a: any, b: any) => {
      const workloadA = a.assignedTickets.length
      const workloadB = b.assignedTickets.length
      if (workloadA !== workloadB) {
        return workloadA - workloadB
      }
      return a.id - b.id
    })
    assigneeId = agents[0].id
  }

  // 3. Create ticket
  const ticket = await context.entities.Ticket.create({
    data: {
      title,
      description,
      priority,
      status: 'OPEN',
      createdAt: now,
      slaDeadline,
      isEscalated: false,
      creatorId: context.user.id,
      assigneeId: assigneeId || undefined
    },
    include: {
      assignee: true,
      creator: true
    }
  })

  return ticket
}

export const simulateSlaBreach = async (args: { ticketId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const { ticketId } = args
  const ticket = await context.entities.Ticket.findUnique({
    where: { id: ticketId }
  })

  if (!ticket) {
    throw new HttpError(404, 'Ticket not found')
  }

  // Subtract 2 hours (2 * 3600 * 1000 milliseconds)
  const twoHours = 2 * 3600 * 1000
  const newCreatedAt = new Date(ticket.createdAt.getTime() - twoHours)
  const newSlaDeadline = new Date(ticket.slaDeadline.getTime() - twoHours)

  // Update in database first
  let updatedTicket = await context.entities.Ticket.update({
    where: { id: ticketId },
    data: {
      createdAt: newCreatedAt,
      slaDeadline: newSlaDeadline
    },
    include: {
      assignee: true,
      creator: true
    }
  })

  // Check if breached (slaDeadline is in the past, status is not RESOLVED, and isEscalated is false)
  const now = new Date()
  const isBreached = updatedTicket.slaDeadline.getTime() < now.getTime() && 
                     updatedTicket.status !== 'RESOLVED' && 
                     !updatedTicket.isEscalated

  if (isBreached) {
    // Find manager with smallest ID
    const managers = await context.entities.User.findMany({
      where: { role: 'MANAGER' },
      orderBy: { id: 'asc' },
      take: 1
    })

    const managerId = managers.length > 0 ? managers[0].id : null

    // Update escalation and assignee
    updatedTicket = await context.entities.Ticket.update({
      where: { id: ticketId },
      data: {
        isEscalated: true,
        assigneeId: managerId !== null ? managerId : updatedTicket.assigneeId
      },
      include: {
        assignee: true,
        creator: true
      }
    })
  }

  return updatedTicket
}

export const resolveTicket = async (args: { ticketId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }
  return context.entities.Ticket.update({
    where: { id: args.ticketId },
    data: { status: 'RESOLVED' },
    include: {
      assignee: true,
      creator: true
    }
  })
}

import { createProviderId, createUser, sanitizeAndSerializeProviderData } from 'wasp/server/auth'

export const seedData = async (prisma: any) => {
  // Clear existing data to ensure clean state
  await prisma.ticket.deleteMany({})
  await prisma.user.deleteMany({})

  // 1. Create manager
  const managerProviderId = createProviderId('username', 'manager')
  const managerProviderData = await sanitizeAndSerializeProviderData({
    hashedPassword: 'password123'
  })
  await createUser(managerProviderId, managerProviderData, {
    username: 'manager',
    password: 'password123',
    role: 'MANAGER'
  })

  // 2. Create agent1
  const agent1ProviderId = createProviderId('username', 'agent1')
  const agent1ProviderData = await sanitizeAndSerializeProviderData({
    hashedPassword: 'password123'
  })
  await createUser(agent1ProviderId, agent1ProviderData, {
    username: 'agent1',
    password: 'password123',
    role: 'AGENT'
  })

  // 3. Create agent2
  const agent2ProviderId = createProviderId('username', 'agent2')
  const agent2ProviderData = await sanitizeAndSerializeProviderData({
    hashedPassword: 'password123'
  })
  await createUser(agent2ProviderId, agent2ProviderData, {
    username: 'agent2',
    password: 'password123',
    role: 'AGENT'
  })

  // 4. Create customer1
  const customer1ProviderId = createProviderId('username', 'customer1')
  const customer1ProviderData = await sanitizeAndSerializeProviderData({
    hashedPassword: 'password123'
  })
  await createUser(customer1ProviderId, customer1ProviderData, {
    username: 'customer1',
    password: 'password123',
    role: 'CUSTOMER'
  })

  console.log('Database seeded successfully!')
}

