                  placeholder="Enter ticket description"
                ></textarea>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
                <label htmlFor="ticket-priority" style={{ fontWeight: 'bold', fontSize: '14px' }}>Priority</label>
